/** Reading packs from a directory (Node). Matching a pack to a service is pack-match.mjs. */
import { readdir, readFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

export { matchPack } from "./pack-match.mjs";

/**
 * The standard packs this package ships (data/packs/), so the default works wherever the package is installed.
 * They are copies of the repository's packs/ (W0's paths), regenerated by `npm run data -w packages/resolver`;
 * test/data.test.mjs fails when a copy is stale.
 */
export const DEFAULT_PACKS_DIR = fileURLToPath(new URL("../data/packs", import.meta.url));

/** Read every `*.profile.json` of kind "pack" in a directory, sorted by file name. Unparseable files are reported, not skipped. */
export async function loadPacks(dir = DEFAULT_PACKS_DIR) {
  const out = [];
  for (const f of (await readdir(dir)).sort()) {
    if (!f.endsWith(".profile.json")) continue;
    const file = path.join(dir, f);
    const doc = JSON.parse(await readFile(file, "utf8"));
    if (doc?.kind === "pack") out.push({ file, doc });
  }
  return out;
}
